#!/usr/bin/env python3
"""Emit src/comb_table.nr, the precomputed table behind `fixed_base::fixed_base_mul`.

Run from the resolver_circuit directory:

    ./scripts/generate_comb_table.py && aztec-nargo fmt

The table is a pure function of `G`, `WINDOW_BITS` and the offset generator below, so rerun it only
when one of those changes. The Noir tests re-derive every entry from curve arithmetic.
"""

import sys
from pathlib import Path

P = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEFFFFFC2F
N = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141
G = (
    0x79BE667EF9DCBBAC55A06295CE870B07029BFCDB2DCE28D959F2815B16F81798,
    0x483ADA7726A3C4655DA4FBFC0E1108A8FD17B448A68554199C47D08FFB10D4B8,
)

# Base-2^120 limbs of a point with no known discrete log relative to G: hash_to_curve("bigcurve
# offset generator").
OFFSET_GENERATOR_LIMBS = (
    (0x7F497CC0B274831D60A9A05D29677E, 0x8726557BF1DD4A0BFDC80BA0F6F13, 0x9046),
    (0xFC449B9F63F4EC1C94BD9E3D802229, 0x63B03856445A4B7D349C9A184F81AC, 0x8D48),
)

WINDOW_BITS = 4
WINDOWS = 256 // WINDOW_BITS
ENTRIES = 1 << WINDOW_BITS


def add(p, q):
    if p is None:
        return q
    if q is None:
        return p
    (x1, y1), (x2, y2) = p, q
    if x1 == x2:
        if (y1 + y2) % P == 0:
            return None
        lam = 3 * x1 * x1 * pow(2 * y1, P - 2, P) % P
    else:
        lam = (y2 - y1) * pow(x2 - x1, P - 2, P) % P
    x3 = (lam * lam - x1 - x2) % P
    return (x3, (lam * (x1 - x3) - y1) % P)


def mul(k, p):
    result = None
    while k:
        if k & 1:
            result = add(result, p)
        p = add(p, p)
        k >>= 1
    return result


def from_limbs(limbs):
    return sum(limb << (120 * i) for i, limb in enumerate(limbs))


def limbs(value):
    return tuple((value >> (120 * i)) & ((1 << 120) - 1) for i in range(3))


def fq(value):
    return "Secp256k1_Fq::from_limbs([0x%030x, 0x%030x, 0x%030x])" % limbs(value)


def offsets():
    """Distinct per-window offsets summing to zero.

    Distinct: a shared offset would make two all-zero-digit windows contribute the same point and
    force a doubling. Summing to zero: the windows accumulate with no correction at the end.
    """
    omega = tuple(from_limbs(l) for l in OFFSET_GENERATOR_LIMBS)
    assert (omega[1] ** 2 - omega[0] ** 3 - 7) % P == 0, "offset generator is not on the curve"

    tail = [mul(1 << i, omega) for i in range(1, WINDOWS)]
    total = None
    for point in tail:
        total = add(total, point)
    head = (total[0], (-total[1]) % P)

    result = [head] + tail
    assert add(head, total) is None, "offsets do not cancel"
    assert len(set(result)) == WINDOWS, "offsets are not distinct"
    return result


def build():
    xs, ys = [], []
    for i, sigma in enumerate(offsets()):
        row = [add(mul((j << (WINDOW_BITS * i)) % N, G) if j else None, sigma) for j in range(ENTRIES)]
        xs.append("    [\n" + "\n".join("        %s," % fq(p[0]) for p in row) + "\n    ],")
        ys.append("    [\n" + "\n".join("        %s," % fq(p[1]) for p in row) + "\n    ],")
    return xs, ys


def main():
    xs, ys = build()
    out = f"""//! Precomputed comb table for secp256k1's generator. Generated by scripts/generate_comb_table.py.
//!
//! `COMB_X[i][j], COMB_Y[i][j]` is `(j * 2^({WINDOW_BITS}*i)) * G + SIGMA_i`, where the offsets `SIGMA_i` are
//! distinct and cancel. Separate x and y arrays keep a witness-indexed read to one lookup per
//! coordinate.
use bignum::{{BigNum, Secp256k1_Fq}};

pub global COMB_WINDOW_BITS: u32 = {WINDOW_BITS};
pub global COMB_WINDOWS: u32 = {WINDOWS};
pub global COMB_ENTRIES: u32 = {ENTRIES};

pub global COMB_X: [[Secp256k1_Fq; {ENTRIES}]; {WINDOWS}] = [
{chr(10).join(xs)}
];

pub global COMB_Y: [[Secp256k1_Fq; {ENTRIES}]; {WINDOWS}] = [
{chr(10).join(ys)}
];
"""
    dest = Path(sys.argv[1] if len(sys.argv) > 1 else "src/comb_table.nr")
    dest.write_text(out)
    print(f"wrote {dest} ({WINDOWS} windows x {ENTRIES} entries)")


if __name__ == "__main__":
    main()
